def max_non_overlapping_substring_length(N, S):
    max_len = 0

    for i in range(N):
        for j in range(i + 1, N):
            length = j - i
            count = 0
            pos = 0

            while True:
                pos = S.find(S[i:i+length], pos)
                if pos == -1:
                    break
                count += 1
                pos += length + 1  # Move to the next possible position to avoid overlapping

            if count >= 2:
                max_len = max(max_len, length)

    return max_len

