def max_repeated_substring_length(N, S):
    from collections import defaultdict

    # Generate all possible substrings and their frequencies
    substr_freq = defaultdict(int)
    for i in range(N):
        for j in range(i + 1, N + 1):
            substring = S[i:j]
            substr_freq[substring] += 1

    # Filter substrings that occur only once
    repeating_substrings = [sub for sub, freq in substr_freq.items() if freq > 1]

    # Function to check if a substring can overlap with another without violating the condition
    def can_overlap(sub1, sub2, len_sub):
        for i in range(N - len_sub + 1):
            if S[i:i+len_sub] == sub1:
                for j in range(i + len_sub, N - len_sub + 1):
                    if S[j:j+len_sub] == sub2:
                        return True
        return False

    # Find the maximum length of valid substrings
    max_len = 0
    for sub in repeating_substrings:
        len_sub = len(sub)
        valid = True
        for other_sub in repeating_substrings:
            if other_sub != sub and can_overlap(sub, other_sub, len_sub):
                valid = False
                break
        if valid:
            max_len = max(max_len, len_sub)

    return max_len

