# Function to calculate the hash of a substring S[start:start+length] using a rolling hash
def rolling_hash(S, start, length, base=26, mod=10**9 + 7):
    hash_value = 0
    for i in range(length):
        hash_value = (hash_value * base + (ord(S[start + i]) - ord('a'))) % mod
    return hash_value

