def max_overlapping_substring_length(S):
    N = len(S)
    max_length = 0
    for length in range(1, N):
        seen = {}
        for start in range(N - length + 1):
            hash_value = rolling_hash(S, start, length)
            if hash_value in seen:
                if start >= seen[hash_value] + length:
                    max_length = max(max_length, length)
            else:
                seen[hash_value] = start
    return max_length

