        return direction, length

    # Find the maximum length and number of sections required
    max_length = 0
    for i in range(N):
        for j in range(i + 1, N):
            x_diff = abs(points[i][0] - points[j][0])
            y_diff = abs(points[i][1] - points[j][1])
            length = max(x_diff, y_diff)
            max_length = max(max_length, length)

    # Determine the number of sections
    m = max_length

    # Determine the directions and lengths for each section
    result = []
    for i in range(N):
        path = ''
        for j in range(i + 1, N):
            x_diff = points[j][0] - points[i][0]
            y_diff = points[j][1] - points[i][1]
            direction, length = determine_direction_and_length(x_diff, y_diff)
            path += direction * length
        result.append(path)

    # Output the result
    output = f"{m}\n1 " * m + "\n".join(result)
