from collections import defaultdict, deque

def find_robot_arm(N, points):
    if N == 0:
        return "0\n0\n\n"

    min_x, max_x = float('inf'), -float('inf')
    min_y, max_y = float('inf'), -float('inf')

    for x, y in points:
        min_x = min(min_x, x)
        max_x = max(max_x, x)
        min_y = min(min_y, y)
        max_y = max(max_y, y)

    # Calculate the minimum number of sections needed
    min_sections = max(abs(min_x), abs(max_x), abs(min_y), abs(max_y))

    # BFS to check if the configuration is feasible
    queue = deque([(0, 0, "")])
    visited = set()

    while queue:
        x, y, path = queue.popleft()
        if (x, y) in visited:
            continue
        visited.add((x, y))

        if (x, y) in points:
            if len(path) == min_sections:
                return f"{min_sections}\n1 {' '.join('1' for _ in range(min_sections))}\n{path}\n"

        if x > min_x:
            queue.append((x - 1, y, path + "L"))
        if x < max_x:
            queue.append((x + 1, y, path + "R"))
        if y > min_y:
            queue.append((x, y - 1, path + "D"))
        if y < max_y:
            queue.append((x, y + 1, path + "U"))

    return "-1"

