def is_valid_assignment(N, A, B):
    # Create a graph to represent the elevator movement
    graph = [[] for _ in range(2 * N + 1)]

    # Add edges to the graph
    for a, b in zip(A, B):
        if a != -1 and b != -1:
            graph[a].append(b)

    # Perform topological sort to ensure the elevator's movement is valid
    in_degree = [0] * (2 * N + 1)
    for u in range(1, 2 * N + 1):
        for v in graph[u]:
            in_degree[v] += 1

    queue = [u for u in range(1, 2 * N + 1) if in_degree[u] == 0]
    topological_order = []

    while queue:
        u = queue.pop(0)
        topological_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if the topological order is valid
    if len(topological_order) != 2 * N:
        return False

    # Check the C_i condition
    for a, b in zip(A, B):
        if a == -1 or b == -1:
            continue
        C = b - a - 1
        for i in range(a + 1, b):
            if a > topological_order.index(i) or b < topological_order.index(i):
                return False

    return True

