import sys

def find_cycles(n, edges):
    adj_list = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)
    out_degree = [0] * (n + 1)

    for a, b in edges:
        adj_list[a].append(b)
        in_degree[b] += 1
        out_degree[a] += 1

    stack = [i for i in range(1, n + 1) if in_degree[i] == 1 and out_degree[i] == 1]
    visited = [False] * (n + 1)

    while stack:
        node = stack.pop()
        if visited[node]:
            continue
        visited[node] = True

        for neighbor in adj_list[node]:
            stack.append(neighbor)

    cycle_vertices = [i for i in range(1, n + 1) if visited[i]]

    if len(cycle_vertices) < 2:
        return -1

    cycle_edges = set()
    for i in range(len(cycle_vertices)):
        a, b = cycle_vertices[i], cycle_vertices[(i + 1) % len(cycle_vertices)]
        if (a, b) in edges:
            cycle_edges.add((a, b))
        elif (b, a) in edges:
            cycle_edges.add((b, a))

    if not cycle_edges:
        return -1

    return len(cycle_vertices), cycle_vertices

