def find_cycle(graph, n):
    in_degree = [0] * (n + 1)
    out_degree = [0] * (n + 1)
    for u, v in graph:
        in_degree[v] += 1
        out_degree[u] += 1

    stack = [u for u in range(1, n + 1) if in_degree[u] == 1 and out_degree[u] == 1]
    if not stack:
        return -1

    cycle = []
    while stack:
        u = stack.pop()
        if in_degree[u] != 1 or out_degree[u] != 1:
            return -1
        cycle.append(u)
        for v in graph:
            if v[0] == u:
                in_degree[v[1]] -= 1
                out_degree[v[1]] -= 1
                if in_degree[v[1]] == 1 and out_degree[v[1]] == 1:
                    stack.append(v[1])

    return cycle

