from collections import defaultdict, deque

def find_induced_subgraph(N, M, edges):
    # Step 1: Build the graph and calculate degrees
    adj_list = defaultdict(list)
    in_degree = [0] * (N + 1)
    out_degree = [0] * (N + 1)

    for A, B in edges:
        adj_list[A].append(B)
        in_degree[B] += 1
        out_degree[A] += 1

    # Step 2: Find all vertices with in-degree and out-degree of 1
    potential_vertices = [i for i in range(1, N + 1) if in_degree[i] == 1 and out_degree[i] == 1]

    # Step 3: Use BFS to check if these vertices form a valid subgraph
    visited = set()
    subgraph = []

    for v in potential_vertices:
        if v not in visited:
            queue = deque([v])
            while queue:
                current = queue.popleft()
                if current in visited:
                    continue
                visited.add(current)
                subgraph.append(current)
                for neighbor in adj_list[current]:
                    queue.append(neighbor)

    # Step 4: Check if the subgraph is valid
    if len(subgraph) != len(potential_vertices):
        return -1

    # Step 5: Print the subgraph
    return subgraph

