def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def count_distinct_matrices(N, K, matrix):
    parent = list(range(N * N + 1))
    rank = [0] * (N * N + 1)

    for i in range(N):
        for j in range(i + 1, N):
            if all(matrix[i][k] + matrix[j][k] <= K for k in range(N)):
                union(parent, rank, i * N + j, j * N + i)

    for j in range(N):
        for k in range(j + 1, N):
            if all(matrix[i][j] + matrix[i][k] <= K for i in range(N)):
                union(parent, rank, j * N + k, k * N + j)

    component_count = set()
    for i in range(N):
        for j in range(N):
            component_count.add(find(parent, i * N + j))

    return len(component_count) % MOD

