def can_swap_column(matrix, col1, col2):
    for row in range(len(matrix)):
        if matrix[row][col1] + matrix[row][col2] > K:
            return False
    return True

def can_swap_row(matrix, row1, row2):
    for col in range(len(matrix[row1])):
        if matrix[row1][col] + matrix[row2][col] > K:
            return False
    return True

def backtrack(matrix, col_map, row_map, seen):
    if tuple(tuple(row) for row in matrix) in seen:
        return 0
    seen.add(tuple(tuple(row) for row in matrix))

    count = 1
    for i in range(len(col_map)):
        for j in range(i + 1, len(col_map)):
            if can_swap_column(matrix, col_map[i], col_map[j]):
                matrix[i], matrix[j] = matrix[j], matrix[i]
                count = (count + backtrack(matrix, col_map, row_map, seen)) % MOD
                matrix[i], matrix[j] = matrix[j], matrix[i]

    for i in range(len(row_map)):
        for j in range(i + 1, len(row_map)):
            if can_swap_row(matrix, row_map[i], row_map[j]):
                matrix[row_map[i]], matrix[row_map[j]] = matrix[row_map[j]], matrix[row_map[i]]
                count = (count + backtrack(matrix, col_map, row_map, seen)) % MOD
                matrix[row_map[i]], matrix[row_map[j]] = matrix[row_map[j]], matrix[row_map[i]]

    return count

