def count_permutations(row, K):
    n = len(row)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if sum(row[i]) <= K and sum(row[j]) <= K:
                count += 1
    return count

def count_valid_matrices(matrix, K):
    n = len(matrix)
    row_permutations = [0] * n
    col_permutations = [0] * n

    # Count permutations for each row
    for i in range(n):
        row_permutations[i] = count_permutations(matrix[i], K)

    # Count permutations for each column
    for j in range(n):
        col_permutations[j] = count_permutations([matrix[i][j] for i in range(n)], K)

    # Calculate the product of permutations
    result = 1
    for perm in row_permutations:
        result = (result * perm) % MOD

    for perm in col_permutations:
        result = (result * perm) % MOD

    return result

