def is_valid_tournament(N, A):
    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for i in range(N):
        for j in range(N-1):
            graph[i+1].append(A[i][j])

    # Function to check if all nodes are in cycles
    def dfs(node, visited, rec_stack):
        visited[node] = True
        rec_stack[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[node] = False
        return False

    visited = [False] * (N + 1)
    rec_stack = [False] * (N + 1)

    for node in range(1, N + 1):
        if not visited[node]:
            if dfs(node, visited, rec_stack):
                return -1

    # Check if the graph has N edges in total
    num_edges = sum(len(graph[node]) for node in graph) // 2
    if num_edges != N * (N - 1) // 2:
        return -1

    # Find the number of cycles
    def find_cycles(node, visited, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if find_cycles(neighbor, visited, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    visited = [False] * (N + 1)
    num_cycles = 0

    for node in range(1, N + 1):
        if not visited[node]:
            if find_cycles(node, visited, -1):
                return -1
            num_cycles += 1

    return num_cycles

