def is_bipartite(graph, n):
    color = [-1] * (n + 1)
    for i in range(1, n + 1):
        if color[i] == -1:
            queue = deque([i])
            color[i] = 0
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

def hopcroft_karp(graph, n):
    match = [-1] * (n + 1)
    dist = [-1] * (n + 1)

    def bfs():
        for u in range(1, n + 1):
            if match[u] == -1 and dist[u] == -1:
                dist[u] = 0
                queue = deque([u])
                while queue:
                    u = queue.popleft()
                    for v in graph[u]:
                        if match[v] == -1:
                            dist[v] = dist[u] + 1
                            queue.append(v)
                        elif dist[v] == -1 and dist[match[v]] == dist[u] + 1:
                            dist[v] = dist[u] + 1
                            queue.append(v)
                    if match[u] != -1 and dist[match[u]] == -1:
                        dist[match[u]] = dist[u] + 1
                        queue.append(match[u])
        return max(dist[u] != -1 for u in range(1, n + 1))

    def dfs(u):
        for v in graph[u]:
            if dist[v] == dist[u] + 1:
                dist[v] = -1
                if match[v] == -1 or dfs(match[v]):
                    match[v] = u
                    match[u] = v
                    return True
        return False

    while bfs():
        for u in range(1, n + 1):
            if match[u] == -1 and dfs(u):
                pass
    return sum(1 for u in range(1, n + 1) if match[u] != -1)

