def can_schedule_matches(N, A):
    from collections import defaultdict, deque

    # Build the directed graph
    graph = defaultdict(list)
    in_degree = [0] * (N + 1)

    for i in range(N):
        for j in range(N - 1):
            u, v = i + 1, A[i][j]
            graph[u].append(v)
            in_degree[v] += 1

    # Topological sorting using Kahn's algorithm
    queue = deque([i for i in range(1, N + 1) if in_degree[i] == 0])
    topological_order = []

    while queue:
        u = queue.popleft()
        topological_order.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If there is a cycle, return -1
    if len(topological_order) != N:
        return -1

    # Schedule the matches
    days = [0] * (N + 1)
    available_days = [0] * N

    for u in topological_order:
        for i in range(N):
            if available_days[i] == 0:
                days[u] = i + 1
                available_days[i] = 1
                break

    return max(days)

