def find_min_days(N, sequences):
    # Create a list of sets to represent the graph
    graph = [set() for _ in range(N)]

    # Populate the graph with the given sequences
    for i, seq in enumerate(sequences):
        for j in seq:
            graph[i].add(j - 1)  # Convert to 0-based index

    # Check if there is a valid Hamiltonian path for each player
    def has_hamiltonian_path(player):
        visited = [False] * N
        stack = [player]
        visited[player] = True

        while stack:
            current = stack[-1]
            if len(graph[current]) == 0:
                return False
            neighbor = next(iter(graph[current]))
            if visited[neighbor]:
                graph[current].remove(neighbor)
                if not graph[current]:
                    stack.pop()
            else:
                graph[current].remove(neighbor)
                visited[neighbor] = True
                stack.append(neighbor)

        return True

    for i in range(N):
        if not has_hamiltonian_path(i):
            return -1

    # Calculate the length of the longest cycle
    max_cycle_length = 0

    def dfs(node, visited, path):
        nonlocal max_cycle_length
        visited[node] = True
        path.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, path)
            elif path[-1] == neighbor:
                cycle_length = len(path) - path.index(neighbor)
                max_cycle_length = max(max_cycle_length, cycle_length)
                break

        path.pop()
        visited[node] = False

    visited = [False] * N
    for i in range(N):
        if not visited[i]:
            dfs(i, visited, [])

    return max_cycle_length

