def orientation(p: Tuple[int, int], q: Tuple[int, int], r: Tuple[int, int]) -> int:
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0  # collinear
    elif val > 0:
        return 1  # clockwise
    else:
        return 2  # counterclockwise

def convex_hull(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    n = len(points)
    if n < 3:
        return points

    low = min(points, key=lambda p: (p[0], p[1]))
    upper = []
    lower = []
    for p in points:
        while len(upper) >= 2 and orientation(upper[-2], upper[-1], p) != 2:
            upper.pop()
        upper.append(p)

    for p in reversed(points):
        while len(lower) >= 2 and orientation(lower[-2], lower[-1], p) != 2:
            lower.pop()
        lower.append(p)

    hull = upper[:-1] + lower[:-1]
    return hull

def circumradius(p: Tuple[int, int], q: Tuple[int, int], r: Tuple[int, int]) -> float:
    ax, ay = p[0] - r[0], p[1] - r[1]
    bx, by = q[0] - r[0], q[1] - r[1]
    cx, cy = ax - bx, ay - by
    b = bx * bx + by * by
    c = cx * cx + cy * cy
    d = 2 * (ax * by - ay * bx)
    return abs(b * c - ax * cx * by + bx * cy * ay) / d

