from math import sqrt

def circumcircle_radius(x1, y1, x2, y2, x3, y3):
    D = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2))
    if D == 0:
        # Points are collinear, cannot form a triangle
        return float('inf')

    U = x1**2 + y1**2
    V = x2**2 + y2**2
    W = x3**2 + y3**2

    cx = (1 / D) * (U * (y2 - y3) + V * (y3 - y1) + W * (y1 - y2))
    cy = (1 / D) * (U * (x3 - x2) + V * (x1 - x3) + W * (x2 - x1))

    r = sqrt((cx - x1)**2 + (cy - y1)**2)
    return r

