import math

def distance(p1: Tuple[int, int], p2: Tuple[int, int]) -> float:
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def circle_from_two_points(p1: Tuple[int, int], p2: Tuple[int, int]) -> Tuple[float, Tuple[float, float]]:
    center_x = (p1[0] + p2[0]) / 2
    center_y = (p1[1] + p2[1]) / 2
    radius = distance(p1, p2) / 2
    return radius, (center_x, center_y)

def circle_from_three_points(p1: Tuple[int, int], p2: Tuple[int, int], p3: Tuple[int, int]) -> Tuple[float, Tuple[float, float]]:
    D = 2 * (p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1]))
    U = (p1[0] ** 2 + p1[1] ** 2) * (p2[1] - p3[1]) + (p2[0] ** 2 + p2[1] ** 2) * (p3[1] - p1[1]) + (p3[0] ** 2 + p3[1] ** 2) * (p1[1] - p2[1])
    V = (p1[0] ** 2 + p1[1] ** 2) * (p3[0] - p2[0]) + (p2[0] ** 2 + p2[1] ** 2) * (p1[0] - p3[0]) + (p3[0] ** 2 + p3[1] ** 2) * (p2[0] - p1[0])
    center_x = U / D
    center_y = V / D
    radius = distance((center_x, center_y), p1)
    return radius, (center_x, center_y)

def welzl(points: list, boundary: list) -> Tuple[float, Tuple[float, float]]:
    if not points or len(boundary) == 3:
        if len(boundary) == 0:
            return 0, (0, 0)
        elif len(boundary) == 1:
            return 0, boundary[0]
        elif len(boundary) == 2:
            return circle_from_two_points(boundary[0], boundary[1])

    p = points.pop()
    r, c = welzl(points, boundary)
    if distance(p, c) > r:
        boundary.append(p)
        r, c = welzl(points, boundary)
        boundary.pop()

    points.append(p)
    return r, c

def smallest_enclosing_circle(points: list) -> float:
    r, c = welzl(points, [])
    return r

