def gaussian_elimination(matrix, mod):
    n = len(matrix)
    rank = 0
    i = 0
    for j in range(n):
        pivot = -1
        for ii in range(i, n):
            if matrix[ii][j] == 1:
                pivot = ii
                break
        if pivot == -1:
            continue
        matrix[i], matrix[pivot] = matrix[pivot], matrix[i]
        for ii in range(n):
            if ii != i and matrix[ii][j] == 1:
                for jj in range(n):
                    matrix[ii][jj] = (matrix[ii][jj] + matrix[i][jj]) % mod
        i += 1
        rank += 1
    return rank

