def count_patties_in_burger(N, X):
    # Base case for level-0 burger
    if N == 0:
        return 1

    # Initialize the number of layers and patties
    total_layers = 1
    total_patties = 1

    # Calculate total layers and patties for level-N burger
    while N > 0:
        total_layers = 2 * total_layers + 2
        total_patties = 2 * total_patties + 2
        N -= 1

    # If X is greater than or equal to total layers, Lunlun eats all patties
    if X >= total_layers:
        return total_patties

    # Trace back to count the patties in the bottom-most X layers
    current_layers = total_layers
    current_patties = total_patties
    level = N

    while current_layers > X:
        if current_layers % 4 == 2:
            current_patties -= (current_layers // 4) * 2
        current_layers //= 2
        level -= 1

    return current_patties

