def max_operations(N, points):
    from collections import defaultdict

    # Dictionary to count points that can be part of a rectangle
    rectangle_points = defaultdict(int)

    # Iterate through all pairs of points
    for i in range(N):
        for j in range(i + 1, N):
            x1, y1 = points[i]
            x2, y2 = points[j]

            # Calculate the potential third points that can form a rectangle
            for k in range(N):
                if k == i or k == j:
                    continue
                x3, y3 = points[k]
                if (x3 == x1 and y3 == y2) or (x3 == x2 and y3 == y1):
                    rectangle_points[(x3, y3)] += 1

    # The maximum number of operations is half of the maximum count of points that can be part of a rectangle
    max_points = max(rectangle_points.values())
    return max_points // 2

