def max_operations(N, points):
    # Dictionary to store the count of points with the same x or y coordinates
    count = defaultdict(int)
    for x, y in points:
        count[x] += 1
        count[y] += 1

    # Initialize the result
    result = 0

    # Check for each pair of points
    for i in range(N):
        for j in range(i + 1, N):
            x1, y1 = points[i]
            x2, y2 = points[j]

            # Check if the points can form a rectangle with other points
