                if count[x1] > 2 and count[y2] > 1:
                    result += 1
            elif x1 != x2 and y1 == y2:
                # Check if there are points with the same x and y coordinates
                if count[x2] > 2 and count[y1] > 1:
                    result += 1

    # Each rectangle is counted twice, so we divide by 2
    return result // 2

