    if K == 1:
        return N

    dp = [[0] * (N + 1) for _ in range(K + 1)]

    # Initialize sequences of length 1
    for j in range(1, N + 1):
        dp[1][j] = 1

    # Fill the dp table
    for i in range(2, K + 1):
        for j in range(1, N + 1):
            for p in range(1, j + 1):
                if p * j <= N:
                    dp[i][j] = (dp[i][j] + dp[i-1][p]) % MOD

    # The result is the sum of sequences of length K ending with any element
    result = sum(dp[K]) % MOD
    return result

