    dp = [[0] * W for _ in range(H)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the first row and first column
    for i in range(1, H):
        if i >= A:
            dp[i][0] = 0
        else:
            dp[i][0] = dp[i-1][0]

    for j in range(1, W):
        if j >= B:
            dp[0][j] = 0
        else:
            dp[0][j] = dp[0][j-1]

    # Fill the DP table
    for i in range(1, H):
        for j in range(1, W):
            if i >= A or j >= B:
                dp[i][j] = 0
            else:
                dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD

    return dp[H-1][W-1]

