def min_total_length(N, A):
    if N == 1:
        return 0

    from collections import defaultdict

    # Build the graph
    graph = defaultdict(list)
    for u in range(N):
        for v in range(u + 1, N):
            if A[u][v] > 0:
                graph[u].append((v, A[u][v]))
                graph[v].append((u, A[u][v]))

    # Bellman-Ford check
    def bellman_ford(start):
        dist = [float('inf')] * N
        dist[start] = 0
        for _ in range(N - 1):
            updated = False
            for u in range(N):
                for v, weight in graph[u]:
                    if dist[u] + weight < dist[v]:
                        dist[v] = dist[u] + weight
                        updated = True
            if not updated:
                break
        return all(dist[u] + dist[v] >= A[u][v] for u in range(N) for v in range(u + 1, N))

    for u in range(N):
        if not bellman_ford(u):
            return -1

    # Calculate total road length
    total_length = sum(sum(weight for _, weight in graph[u]) for u in range(N)) // 2
    return total_length

