def bellman_ford(N, A):
    # Initialize distance from start to all vertices as infinity
    dist = [float('inf')] * N
    dist[0] = 0

    # Relax edges repeatedly
    for _ in range(N - 1):
        for u in range(N):
            for v in range(N):
                if A[u][v] != float('inf') and dist[u] != float('inf') and dist[u] + A[u][v] < dist[v]:
                    dist[v] = dist[u] + A[u][v]

    # Check for negative cycles
    for u in range(N):
        for v in range(N):
            if A[u][v] != float('inf') and dist[u] != float('inf') and dist[u] + A[u][v] < dist[v]:
                return float('-inf')

    return dist

def find_min_roads(N, A):
    # Check for negative cycles using Bellman-Ford
    dist = bellman_ford(N, A)

    if dist == float('-inf'):
        return -1

    # If there are negative cycles, return -1
    if dist is None:
        return -1

    # Calculate the total length of the roads
    total_length = 0
    for u in range(N):
        for v in range(N):
            if A[u][v] != float('inf') and dist[u] != float('inf') and dist[u] + A[u][v] == dist[v]:
                total_length += A[u][v]

    return total_length

