def process_queries(N, Q, queries):
    # Initialize the grid and sets to keep track of white stones
    grid = [[0] * N for _ in range(N)]
    white_stones = set()

    # Place initial black stones in the central (N-2) x (N-2) area
    for i in range(1, N-1):
        for j in range(1, N-1):
            grid[i][j] = 1
            white_stones.add((i, j))

    # Place initial white stones on the bottom side and the right side
    for i in range(N):
        if i != N-1:
            grid[N-1][i] = 0
        if i != 0:
            grid[i][N-1] = 0

    # Process each query
    for query in queries:
        action, x = query.split()
        x = int(x) - 1

        if action == '1':
            # Place a white stone on (1, x)
            grid[0][x] = 0
            white_stones.add((0, x))

            # Replace black stones between (1, x) and the first white stone encountered going down
            for i in range(1, N):
                if (i, x) in white_stones:
                    break
                if grid[i][x] == 1:
                    grid[i][x] = 0
                    white_stones.add((i, x))

        elif action == '2':
            # Place a white stone on (x, 1)
            grid[x][0] = 0
            white_stones.add((x, 0))

            # Replace black stones between (x, 1) and the first white stone encountered going right
            for j in range(1, N):
                if (x, j) in white_stones:
                    break
                if grid[x][j] == 1:
                    grid[x][j] = 0
                    white_stones.add((x, j))

    # Count the number of black stones
    black_stones = N * N - len(white_stones)
    return black_stones

