def process_queries(N, Q, queries):
    # Initialize the grid
    grid = [[0] * N for _ in range(N)]
    for i in range(1, N-1):
        for j in range(1, N-1):
            grid[i][j] = 1

    # Process each query
    for query in queries:
        command, x = map(int, query.split())
        if command == 1:
            # Place a white stone at (1, x) and replace black stones below with white
            for i in range(1, N):
                if grid[i][x-1] == 1:
                    grid[i][x-1] = 0
                    break
            grid[0][x-1] = 0
        elif command == 2:
            # Place a white stone at (x, 1) and replace black stones to the right with white
            for j in range(1, N):
                if grid[x-1][j] == 1:
                    grid[x-1][j] = 0
                    break
            grid[x-1][0] = 0

    # Count the remaining black stones
    black_stones = sum(row.count(1) for row in grid)
    return black_stones

