import heapq

def min_cost_to_one(H, W, c, A):
    # Initialize distance matrix to infinity
    dist = [[float('inf')] * 10 for _ in range(10)]

    # Dijkstra's algorithm to find the minimum cost to convert any digit to 1
    def dijkstra(start):
        pq = [(0, start)]
        dist[start][start] = 0
        while pq:
            cost, node = heapq.heappop(pq)
            if cost > dist[start][node]:
                continue
            for next_node in range(10):
                if next_node == node:
                    next_cost = 0
                else:
                    next_cost = c[node][next_node]
                if cost + next_cost < dist[start][next_node]:
                    dist[start][next_node] = cost + next_cost
                    heapq.heappush(pq, (cost + next_cost, next_node))

    # Compute the minimum cost to convert any digit to 1
    for digit in range(10):
        dijkstra(digit)

    # Calculate the total cost to convert all digits in the grid to 1
    total_cost = 0
    for i in range(H):
        for j in range(W):
            if A[i][j] != -1:
                total_cost += dist[A[i][j]][1]

    return total_cost

