def dijkstra(h, w, c, start_digit):
    # Directions to move in the grid (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    # Priority queue to store (cost, digit)
    pq = [(0, start_digit)]
    # Distance matrix to store the minimum cost to reach each digit
    dist = {i: float('inf') for i in range(10)}
    dist[start_digit] = 0

    while pq:
        current_cost, current_digit = heapq.heappop(pq)

        if current_digit == 1:
            return current_cost

        for di, dj in directions:
            new_digit = 10 * current_digit + di * 10 + dj
            if 0 <= new_digit <= 9:
                new_cost = current_cost + c[current_digit][new_digit]
                if new_cost < dist[new_digit]:
                    dist[new_digit] = new_cost
                    heapq.heappush(pq, (new_cost, new_digit))

    return float('inf')

