def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def min_operations(H, W, c, A):
    parent = list(range(10))
    rank = [0] * 10
    cost = [float('inf')] * 10
    cost[1] = 0

    for i in range(H):
        for j in range(W):
            if A[i][j] != -1:
                digit = A[i][j]
                if digit == 1:
                    continue
                for d in range(10):
                    if c[digit][d] < cost[d]:
                        cost[d] = c[digit][d]
                        union(parent, rank, digit, d)

    return sum(cost[d] for d in range(2, 10))

