def build_segment_tree(n):
    tree = [0] * (4 * n)

    def update(index, value, tree_index, start, end):
        if start == end:
            tree[tree_index] = value
        else:
            mid = (start + end) // 2
            if index <= mid:
                update(index, value, 2 * tree_index + 1, start, mid)
            else:
                update(index, value, 2 * tree_index + 2, mid + 1, end)
            tree[tree_index] = tree[2 * tree_index + 1] + tree[2 * tree_index + 2]

    def query(left, right, tree_index, start, end):
        if left > end or right < start:
            return 0
        if left <= start and right >= end:
            return tree[tree_index]
        mid = (start + end) // 2
        return query(left, right, 2 * tree_index + 1, start, mid) + query(left, right, 2 * tree_index + 2, mid + 1, end)

    return update, query

