class Solution:
    def solve(self, N, edges):
        from collections import defaultdict, deque

        # Build the tree
        tree = defaultdict(list)
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        # Initialize subtree sizes
        subtree_sizes = [0] * (N + 1)

        # DFS to calculate subtree sizes
        def dfs(node, parent):
            size = 1
            for neighbor in tree[node]:
                if neighbor != parent:
                    size += dfs(neighbor, node)
            subtree_sizes[node] = size
            return size

        dfs(1, -1)

        # Initialize the result
        result = 0

        # Calculate the number of connected components
        for L in range(1, N + 1):
            for R in range(L, N + 1):
                # Calculate the number of connected components in the subgraph (L, R)
                if R == L:
                    result += 1
                else:
                    # For each vertex in the range [L, R], check the number of connected components
                    for v in range(L, R + 1):
                        # Include the subtree sizes and exclude the edges outside the range [L, R]
                        result += 1

        return result

