    total_components = 0
    for root in range(L, R + 1):
        visited = [False] * (n + 1)
        stack = [root]
        component_count = 0
        while stack:
            node = stack.pop()
            if not visited[node]:
                component_count += 1
                dfs(graph, node, visited, node)
        total_components += component_count
    return total_components

