def kmp_search(haystack, needle):
    # Compute the prefix function (pi array)
    pi = [0] * len(needle)
    j = 0
    for i in range(1, len(needle)):
        while j > 0 and needle[j] != needle[i]:
            j = pi[j - 1]
        if needle[j] == needle[i]:
            j += 1
        pi[i] = j

    # KMP search
    j = 0
    positions = []
    for i in range(len(haystack)):
        while j > 0 and needle[j] != haystack[i]:
            j = pi[j - 1]
        if needle[j] == haystack[i]:
            j += 1
        if j == len(needle):
            positions.append(i - j + 1)
            j = pi[j - 1]
    return positions

def max_i(s, t):
    if not t:
        return -1  # If t is empty, there are infinitely many i

    if not s:
        return 0  # If s is empty, t can only be a substring once

    # Find all positions of t in s using KMP
    positions = kmp_search(s, t)

    # Determine the maximum i
    max_i = 0
    if positions:
        max_i = max(positions) // len(t)

    return max_i

