def max_changes_to_black(H, W, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * W for _ in range(H)]
    dist = [[float('inf')] * W for _ in range(H)]
    dist[0][0] = 0

    pq = [(0, 0, 0)]
    while pq:
        d, x, y = heapq.heappop(pq)
        if visited[x][y]:
            continue
        visited[x][y] = True
        if x == H - 1 and y == W - 1:
            break

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny]:
                new_dist = d + (grid[nx][ny] == '.')
                if new_dist < dist[nx][ny]:
                    dist[nx][ny] = new_dist
                    heapq.heappush(pq, (new_dist, nx, ny))

    if dist[H-1][W-1] == float('inf'):
        return -1

    black_on_path = sum(grid[i][j] == '#' for i in range(H) for j in range(W) if dist[i][j] != float('inf'))
    total_white = H * W - sum(grid[i][j] == '#' for i in range(H) for j in range(W))

    return total_white - black_on_path

