def dfs(grid, H, W, x, y, visited, changes):
    if not is_valid(x, y, H, W) or grid[x][y] == '#' or visited[x][y]:
        return changes - 1 if (x, y) == (H-1, W-1) else -1
    visited[x][y] = True
    if grid[x][y] == '.':
        changes += 1
    max_changes = -1
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
