def spiral_fill(grid, H, W, target_color, count):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up
    r, c = H // 2, W // 2
    dr, dc = 0, 0
    step = 0

    while count > 0:
        grid[r][c] = target_color
        count -= 1

        if step == 0 or step % 2 == 0:
            dr, dc = directions[(directions.index((dr, dc)) + 1) % 4]
            step += 1

        r += dr
        c += dc

