def find_unbalanced_substring(s):
    n = len(s)
    for size in range(2, n + 1):
        for start in range(n - size + 1):
            end = start + size
            freq = {}
            for char in s[start:end]:
                if char in freq:
                    freq[char] += 1
                else:
                    freq[char] = 1
                if freq[char] > size // 2:
                    return start + 1, end
    return -1, -1

