def find_unbalanced_substring(s):
    n = len(s)
    for i in range(n):
        char_count = {}
        for j in range(i, n):
            char_count[s[j]] = char_count.get(s[j], 0) + 1
            if char_count[s[j]] > (j - i + 1) // 2:
                return i + 1, j + 1
    return -1, -1

# Read input from standard input
s = input().strip()

# Find the unbalanced substring
start, end = find_unbalanced_substring(s)

